import { InventoryReservations } from '../../lib/parcel-kit.js';

export async function holdEventPackages(eventId, packages) {
  const issues = [];
  const holds = [];
  for (const pack of packages) {
    if (!pack.stockCode || !Number.isInteger(pack.count) || pack.count <= 0) {
      issues.push('Invalid package');
      continue;
    }
    holds.push(await InventoryReservations.reserve({
      orderId: eventId, sku: pack.stockCode, quantity: pack.count,
    }));
  }
  return { issues, holds };
}

